-- AUTOMATISCH ERZEUGT aus daten/ (npm run seed) – nicht von Hand bearbeiten.
-- Teil von supabase/seed.sql: Thema 15 „Autofahren“ – Instrumente, Maßnahmen, Prüfeinheiten, Abdeckung.
-- Nach 0-gemeinsam.sql ausführen. Mehrfach ausführbar, gespielte Runden bleiben erhalten.

begin;

delete from public.massnahmen where thema_id = 15;
delete from public.abdeckung where thema_id = 15;
delete from public.pruef_einheiten where thema_id = 15;

-- Lösungswege für die Forderungskarte (ohne Punkte). Upsert, damit gespeicherte Forderungen ihren Verweis behalten.
insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft, nebenwirkungen) values
  (7011, 15, 'CO₂-Preis auf Kraftstoffe abschaffen', 'Senkt den Spritpreis 2026 um rund 15 bis 18 Cent je Liter; ab 2028 gilt aber der europäische Emissionshandel für Verkehr, den Deutschland nicht allein abschaffen kann. Die Einnahmen fehlen für Entlastungen an anderer Stelle.', 'belegt', null, 'bund', null, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Der nationale Emissionshandel brachte 2025 rund 16 Mrd. Euro ein, die vollständig in den Klima- und Transformationsfonds fließen; bei Abschaffung des CO₂-Preises entfielen sie dort.","quelle_url":"https://www.umweltbundesamt.de/presse/pressemitteilungen/emissionshandel-21-milliarden-euro-fliessen-in-den","belegstufe":"A"},{"bereich":"umwelt","richtung":"nachteil","text":"Eine UBA-Modellierung beziffert die zusätzliche Minderung durch einen CO₂-Preis im Verkehr auf 7 Mio. t CO₂-Äq. im Jahr 2030 (kumuliert 116 Mio. t bis 2045); ohne ihn entfiele sie.","quelle_url":"https://www.umweltbundesamt.de/themen/verkehr/klimaschutz-im-verkehr","belegstufe":"B"}]'::jsonb),
  (7012, 15, 'CO₂-Einnahmen als Klimageld oder Klimabonus zurückzahlen', 'Gleicht die Mehrkosten durch den CO₂-Preis für viele Haushalte aus, senkt den Spritpreis aber nicht; wer viel fahren muss, wird nur teilweise entlastet. Ein Auszahlungsweg an alle Haushalte muss erst aufgebaut werden.', 'gemischt', null, 'bund', null, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Die Einnahmen des nationalen Emissionshandels (rund 16 Mrd. Euro 2025) fließen bisher vollständig in den Klima- und Transformationsfonds; bei Rückzahlung fehlten sie dort.","quelle_url":"https://www.umweltbundesamt.de/presse/pressemitteilungen/emissionshandel-21-milliarden-euro-fliessen-in-den","belegstufe":"A"},{"bereich":"verteilung","richtung":"vorteil","text":"Eine pauschale Auszahlung pro Kopf enthält laut DIW wegen des nach Einkommen unterschiedlichen CO₂-Fußabdrucks bereits eine öko-soziale Komponente: Geringere Einkommen profitieren relativ stärker.","quelle_url":"https://www.diw.de/de/diw_01.c.935747.de/publikationen/wochenberichte/2025_06_1/mehr_klarheit_schaffen__klimageld_als_sozialer_ausgleich_bei_hoeheren_co___-preisen.html","belegstufe":"B"}]'::jsonb),
  (7013, 15, 'Pendlerpauschale erhöhen', 'Entlastet Pendelnde über die Steuer; wer wenig verdient und kaum Steuern zahlt, hat wenig davon.', 'gemischt', null, 'bund', null, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Die Erhöhung der Entfernungspauschale auf 38 Cent ab dem ersten Kilometer kostet 2026 rund 1,1 Mrd. Euro (Jahreswirkung) und bei voller Jahreswirkung knapp 2 Mrd. Euro Steuereinnahmen.","quelle_url":"https://www.bundestag.de/presse/hib/kurzmeldungen-1104874","belegstufe":"A"},{"bereich":"umwelt","richtung":"nachteil","text":"Das Umweltbundesamt sieht in der Entfernungspauschale einen Anreiz, der Zersiedelung der Landschaft und Verkehrswachstum begünstigt.","quelle_url":"https://www.umweltbundesamt.de/presse/pressemitteilungen/umweltschaedliche-subventionen-liegen-bei-ueber-52","belegstufe":"A"},{"bereich":"verteilung","richtung":"nachteil","text":"Von rund 5 Mrd. Euro Steuerentlastung durch die Entfernungspauschale 2025 dürfte rund 1 Mrd. Euro auf 1,7 Mio. Personen mit einem Einkommen über 122.919 Euro entfallen.","quelle_url":"https://www.bundestag.de/presse/hib/kurzmeldungen-1104874","belegstufe":"A"}]'::jsonb),
  (7014, 15, 'Kaufförderung für Elektroautos für kleine und mittlere Einkommen (Prämie, Steuerabzug, Leasing)', 'Setzt direkt am Preis an, den Haushalte als größtes Hindernis nennen; soziales Leasing hat in Frankreich viele Haushalte mit kleinem Einkommen erreicht. Frühere Prämien in Deutschland wurden zum Teil mitgenommen und kamen vor allem besser Verdienenden zugute.', 'gemischt', 'https://www.kfw.de/PDF/Download-Center/Konzernthemen/Research/PDF-Dokumente-KfW-Energiewendebarometer/KfW-Energiewendebarometer-2026.pdf', 'bund', null, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Der frühere Umweltbonus (2016–2023) umfasste bewilligte Fördermittel von 10,2 Mrd. Euro für rund 2,17 Mio. Fahrzeuge; das sind nicht die Kosten dieser Maßnahme.","quelle_url":"https://technopolis-group.com/?p=61750","belegstufe":"B"},{"bereich":"umwelt","richtung":"vorteil","text":"Zum Vergleich: Der frühere Umweltbonus (2016–2023) brachte laut Evaluation brutto 7,3 Mt CO₂-Äq. Treibhausgaseinsparung; das ist nicht die Wirkung dieser Maßnahme.","quelle_url":"https://technopolis-group.com/?p=61750","belegstufe":"B"},{"bereich":"verteilung","richtung":"nachteil","text":"Zum Vergleich: Die frühere Umweltbonus-Förderung nutzten laut Evaluation überproportional Haushalte mit höherem Nettoeinkommen; die Evaluation spricht von einem unerwünschten Verteilungseffekt.","quelle_url":"https://technopolis-group.com/?p=61750","belegstufe":"B"}]'::jsonb),
  (7015, 15, 'Öffentliche Ladeinfrastruktur ausbauen und Ladepreise senken', 'Hilft, wer nicht zu Hause laden kann, vor allem in Mehrparteienhäusern; öffentliches Laden bleibt aber meist teurer und aufwendiger als eine eigene Wallbox.', 'gemischt', null, 'bund', null, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Der Haushaltsentwurf 2026 sieht für die Errichtung von Tank- und Ladeinfrastruktur 1,7 Mrd. Euro vor; das sind nicht die Kosten dieser Maßnahme.","quelle_url":"https://www.bundestag.de/presse/hib/kurzmeldungen-1111618","belegstufe":"A"}]'::jsonb),
  (7258, 15, 'Elektro- und verbrauchsarme Fahrzeuge fördern, um weniger Kraftstoff zu brauchen (Bund, Ölabhängigkeit)', 'Jedes ersetzte Verbrennerfahrzeug braucht kein Benzin oder Diesel mehr. Bei 4,1 % Elektroanteil im Pkw-Bestand (1. 1. 2026) und langer Erneuerungszeit wirkt das erst über Jahre und schützt nicht vor einem Preisschock im laufenden Jahr.', 'gemischt', 'https://www.kba.de/DE/Presse/Pressemitteilungen/Fahrzeugbestand/2026/pm09_fz_bestand_pm_komplett.html', 'bund', null, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Das 2026 gestartete Bundesprogramm für E-Auto-Prämien umfasst 3 Mrd. Euro bis 2029 für geschätzt 800.000 Fahrzeuge; es sind nicht die Kosten dieser Maßnahme.","quelle_url":"https://www.bundesumweltministerium.de/PM11760","belegstufe":"A"},{"bereich":"umwelt","richtung":"vorteil","text":"Laut Umweltbundesamt sind 2020 zugelassene Elektroautos über den gesamten Lebenszyklus rund 40 Prozent klimafreundlicher als Benziner; für 2030 werden rund 55 Prozent erwartet.","quelle_url":"https://www.umweltbundesamt.de/en/press/pressinformation/climate-benefit-for-electric-cars-confirmed","belegstufe":"A"}]'::jsonb),
  (7259, 15, 'Alternative Kraftstoffe wie E-Fuels zulassen und gleichstellen (Bund, Ölabhängigkeit)', 'Strombasierte Kraftstoffe entkoppeln den Preis vom Rohöl, sind aber nicht kommerziell verfügbar und würden zunächst etwa 2 Euro je Liter kosten (Benzin im Großhandel 0,50). Bis 2035 deckt es höchstens die Hälfte des Bedarfs von Luft-, Schifffahrt und Chemie. Das Verbrennerverbot ist EU-Recht.', 'offen', 'https://www.pik-potsdam.de/members/Ueckerdt/E-Fuels_Stand-und-Projektionen_PIK-Potsdam.pdf', 'bund', null, true, null, '[{"bereich":"umwelt","richtung":"nachteil","text":"Laut Umweltbundesamt brauchen strombasierte Kraftstoffe im Pkw für dieselbe Fahrleistung die drei- bis sechsfache Strommenge eines Elektroautos und gelten als hochgradig ineffizient.","quelle_url":"https://www.umweltbundesamt.de/themen/verkehr/kraftstoffe-antriebe","belegstufe":"A"}]'::jsonb),
  (7260, 15, 'Energie- und Umsatzsteuer in Preiskrisen schnell senken (Bund)', 'Senkt den Preis sofort, aber nur befristet; der Tankrabatt 2026 kam laut Monopolkommission zu einem großen Teil, aber nicht vollständig an. Die schnelle Senkung der Umsatzsteuer braucht EU-Zustimmung. Das Programm nennt Güter des täglichen Bedarfs, nicht nur Kraftstoff.', 'gemischt', 'https://www.monopolkommission.de/fileadmin/monopolkommission/Indexierte_Dateien/PDFs/Policy_Briefs/Monopolkommission-Policy-Brief-16-2026-Tankrabatt.pdf#page=1', 'bund', null, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Die befristete Senkung um 14,04 Cent je Liter von Mai bis Juni 2026 kostete laut Gesetzentwurf 1,6 Mrd. Euro; das sind nicht die Kosten dieser Maßnahme.","quelle_url":"https://www.bundestag.de/presse/hib/kurzmeldungen-1165456","belegstufe":"A"},{"bereich":"umwelt","richtung":"nachteil","text":"Laut Gesetzentwurf begünstigt eine Senkung der Energiesteuer den Einsatz fossiler Energien vorübergehend und kann den Kraftstoffverbrauch zeitweise steigern.","quelle_url":"https://www.bundestag.de/presse/hib/kurzmeldungen-1165456","belegstufe":"A"},{"bereich":"verteilung","richtung":"nachteil","text":"Zum Vergleich (Tankrabatt 2022): Laut DIW entlastet er eher wohlhabende Haushalte, die viel mit großen Autos fahren, und wirkt wie eine Umverteilung von unten nach oben.","quelle_url":"https://www.diw.de/de/diw_01.c.861731.de/nachrichten/entlastung_fuer_autofahrer__der_tankrabatt_ist_das_naheliegendste__aber_auch_schlechteste_instrument.html","belegstufe":"B"}]'::jsonb)
on conflict (id) do update set thema_id = excluded.thema_id, name = excluded.name, begruendung = excluded.begruendung,
  evidenz = excluded.evidenz, beleg_studie_url = excluded.beleg_studie_url, ebene = excluded.ebene,
  entspricht = excluded.entspricht, ki_entwurf = excluded.ki_entwurf, entwurf_herkunft = excluded.entwurf_herkunft,
  nebenwirkungen = excluded.nebenwirkungen;

delete from public.instrumente where thema_id = 15 and id not in (7011, 7012, 7013, 7014, 7015, 7258, 7259, 7260);

insert into public.massnahmen (id, thema_id, partei_id, land, beschreibung, ursachen_ids, instrument_id, wirksamkeit, umsetzbarkeit,
  rollen_modifikator, begruendung, beleg_programm_url, beleg_studie_url, evidenz, stand, geprueft, ki_entwurf, entwurf_herkunft, nebenwirkungen) values
  (7016, 15, 11, null, 'Pendlerpauschale erhöhen', '{1502}', 7013, 1, 3, null, 'Entlastet Pendelnde über die Steuer; wer wenig verdient und kaum Steuern zahlt, hat wenig davon.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=14', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Die Erhöhung der Entfernungspauschale auf 38 Cent ab dem ersten Kilometer kostet 2026 rund 1,1 Mrd. Euro (Jahreswirkung) und bei voller Jahreswirkung knapp 2 Mrd. Euro Steuereinnahmen.","quelle_url":"https://www.bundestag.de/presse/hib/kurzmeldungen-1104874","belegstufe":"A"},{"bereich":"umwelt","richtung":"nachteil","text":"Das Umweltbundesamt sieht in der Entfernungspauschale einen Anreiz, der Zersiedelung der Landschaft und Verkehrswachstum begünstigt.","quelle_url":"https://www.umweltbundesamt.de/presse/pressemitteilungen/umweltschaedliche-subventionen-liegen-bei-ueber-52","belegstufe":"A"},{"bereich":"verteilung","richtung":"nachteil","text":"Von rund 5 Mrd. Euro Steuerentlastung durch die Entfernungspauschale 2025 dürfte rund 1 Mrd. Euro auf 1,7 Mio. Personen mit einem Einkommen über 122.919 Euro entfallen.","quelle_url":"https://www.bundestag.de/presse/hib/kurzmeldungen-1104874","belegstufe":"A"}]'::jsonb),
  (7017, 15, 11, null, 'Klimabonus aus den CO₂-Einnahmen', '{1502}', 7012, 1, 2, null, 'Gleicht die Mehrkosten durch den CO₂-Preis für viele Haushalte aus, senkt den Spritpreis aber nicht; wer viel fahren muss, wird nur teilweise entlastet. Ein Auszahlungsweg an alle Haushalte muss erst aufgebaut werden.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=24', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Die Einnahmen des nationalen Emissionshandels (rund 16 Mrd. Euro 2025) fließen bisher vollständig in den Klima- und Transformationsfonds; bei Rückzahlung fehlten sie dort.","quelle_url":"https://www.umweltbundesamt.de/presse/pressemitteilungen/emissionshandel-21-milliarden-euro-fliessen-in-den","belegstufe":"A"},{"bereich":"verteilung","richtung":"vorteil","text":"Eine pauschale Auszahlung pro Kopf enthält laut DIW wegen des nach Einkommen unterschiedlichen CO₂-Fußabdrucks bereits eine öko-soziale Komponente: Geringere Einkommen profitieren relativ stärker.","quelle_url":"https://www.diw.de/de/diw_01.c.935747.de/publikationen/wochenberichte/2025_06_1/mehr_klarheit_schaffen__klimageld_als_sozialer_ausgleich_bei_hoeheren_co___-preisen.html","belegstufe":"B"}]'::jsonb),
  (7018, 15, 11, null, 'Ladeinfrastruktur angemessen ausbauen', '{1505}', 7015, 1, 3, null, 'Hilft, wer nicht zu Hause laden kann, vor allem in Mehrparteienhäusern; öffentliches Laden bleibt aber meist teurer und aufwendiger als eine eigene Wallbox.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=74', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Der Haushaltsentwurf 2026 sieht für die Errichtung von Tank- und Ladeinfrastruktur 1,7 Mrd. Euro vor; das sind nicht die Kosten dieser Maßnahme.","quelle_url":"https://www.bundestag.de/presse/hib/kurzmeldungen-1111618","belegstufe":"A"}]'::jsonb),
  (7019, 15, 12, null, 'Befristeter Steuerabzugsbetrag für in Deutschland produzierte E-Autos, auch Gebrauchte und Leasing', '{1504}', 7014, 2, 3, null, 'Setzt direkt am Preis an, den Haushalte als größtes Hindernis nennen; soziales Leasing hat in Frankreich viele Haushalte mit kleinem Einkommen erreicht. Frühere Prämien in Deutschland wurden zum Teil mitgenommen und kamen vor allem besser Verdienenden zugute.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=7', 'https://www.kfw.de/PDF/Download-Center/Konzernthemen/Research/PDF-Dokumente-KfW-Energiewendebarometer/KfW-Energiewendebarometer-2026.pdf', 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Der frühere Umweltbonus (2016–2023) umfasste bewilligte Fördermittel von 10,2 Mrd. Euro für rund 2,17 Mio. Fahrzeuge; das sind nicht die Kosten dieser Maßnahme.","quelle_url":"https://technopolis-group.com/?p=61750","belegstufe":"B"},{"bereich":"umwelt","richtung":"vorteil","text":"Zum Vergleich: Der frühere Umweltbonus (2016–2023) brachte laut Evaluation brutto 7,3 Mt CO₂-Äq. Treibhausgaseinsparung; das ist nicht die Wirkung dieser Maßnahme.","quelle_url":"https://technopolis-group.com/?p=61750","belegstufe":"B"},{"bereich":"verteilung","richtung":"nachteil","text":"Zum Vergleich: Die frühere Umweltbonus-Förderung nutzten laut Evaluation überproportional Haushalte mit höherem Nettoeinkommen; die Evaluation spricht von einem unerwünschten Verteilungseffekt.","quelle_url":"https://technopolis-group.com/?p=61750","belegstufe":"B"}]'::jsonb),
  (7020, 15, 12, null, 'Laden an öffentlichen Ladesäulen günstiger als Tanken, Schnellladepflicht für Tankstellen', '{1505}', 7015, 1, 3, null, 'Hilft, wer nicht zu Hause laden kann, vor allem in Mehrparteienhäusern; öffentliches Laden bleibt aber meist teurer und aufwendiger als eine eigene Wallbox.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=7', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Der Haushaltsentwurf 2026 sieht für die Errichtung von Tank- und Ladeinfrastruktur 1,7 Mrd. Euro vor; das sind nicht die Kosten dieser Maßnahme.","quelle_url":"https://www.bundestag.de/presse/hib/kurzmeldungen-1111618","belegstufe":"A"}]'::jsonb),
  (7021, 15, 12, null, 'Klimageld, wenn ab 2027 der europäische CO₂-Preis gilt', '{1502}', 7012, 1, 2, null, 'Gleicht die Mehrkosten durch den CO₂-Preis für viele Haushalte aus, senkt den Spritpreis aber nicht; wer viel fahren muss, wird nur teilweise entlastet. Ein Auszahlungsweg an alle Haushalte muss erst aufgebaut werden.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=34', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Die Einnahmen des nationalen Emissionshandels (rund 16 Mrd. Euro 2025) fließen bisher vollständig in den Klima- und Transformationsfonds; bei Rückzahlung fehlten sie dort.","quelle_url":"https://www.umweltbundesamt.de/presse/pressemitteilungen/emissionshandel-21-milliarden-euro-fliessen-in-den","belegstufe":"A"},{"bereich":"verteilung","richtung":"vorteil","text":"Eine pauschale Auszahlung pro Kopf enthält laut DIW wegen des nach Einkommen unterschiedlichen CO₂-Fußabdrucks bereits eine öko-soziale Komponente: Geringere Einkommen profitieren relativ stärker.","quelle_url":"https://www.diw.de/de/diw_01.c.935747.de/publikationen/wochenberichte/2025_06_1/mehr_klarheit_schaffen__klimageld_als_sozialer_ausgleich_bei_hoeheren_co___-preisen.html","belegstufe":"B"}]'::jsonb),
  (7022, 15, 13, null, 'Staatliche Unterstützung beim Kauf verbrauchsarmer E-Autos, Social Leasing, Ladekarte', '{1504}', 7014, 2, 3, null, 'Setzt direkt am Preis an, den Haushalte als größtes Hindernis nennen; soziales Leasing hat in Frankreich viele Haushalte mit kleinem Einkommen erreicht. Frühere Prämien in Deutschland wurden zum Teil mitgenommen und kamen vor allem besser Verdienenden zugute.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=40', 'https://www.kfw.de/PDF/Download-Center/Konzernthemen/Research/PDF-Dokumente-KfW-Energiewendebarometer/KfW-Energiewendebarometer-2026.pdf', 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Der frühere Umweltbonus (2016–2023) umfasste bewilligte Fördermittel von 10,2 Mrd. Euro für rund 2,17 Mio. Fahrzeuge; das sind nicht die Kosten dieser Maßnahme.","quelle_url":"https://technopolis-group.com/?p=61750","belegstufe":"B"},{"bereich":"umwelt","richtung":"vorteil","text":"Zum Vergleich: Der frühere Umweltbonus (2016–2023) brachte laut Evaluation brutto 7,3 Mt CO₂-Äq. Treibhausgaseinsparung; das ist nicht die Wirkung dieser Maßnahme.","quelle_url":"https://technopolis-group.com/?p=61750","belegstufe":"B"},{"bereich":"verteilung","richtung":"nachteil","text":"Zum Vergleich: Die frühere Umweltbonus-Förderung nutzten laut Evaluation überproportional Haushalte mit höherem Nettoeinkommen; die Evaluation spricht von einem unerwünschten Verteilungseffekt.","quelle_url":"https://technopolis-group.com/?p=61750","belegstufe":"B"}]'::jsonb),
  (7023, 15, 13, null, 'Überzogene Preise an Ladesäulen beenden', '{1505}', 7015, 1, 3, null, 'Hilft, wer nicht zu Hause laden kann, vor allem in Mehrparteienhäusern; öffentliches Laden bleibt aber meist teurer und aufwendiger als eine eigene Wallbox.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=40', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Der Haushaltsentwurf 2026 sieht für die Errichtung von Tank- und Ladeinfrastruktur 1,7 Mrd. Euro vor; das sind nicht die Kosten dieser Maßnahme.","quelle_url":"https://www.bundestag.de/presse/hib/kurzmeldungen-1111618","belegstufe":"A"}]'::jsonb),
  (7024, 15, 13, null, 'Sozial gestaffeltes Klimageld aus den CO₂-Einnahmen', '{1502}', 7012, 1, 2, null, 'Gleicht die Mehrkosten durch den CO₂-Preis für viele Haushalte aus, senkt den Spritpreis aber nicht; wer viel fahren muss, wird nur teilweise entlastet. Ein Auszahlungsweg an alle Haushalte muss erst aufgebaut werden.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=40', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Die Einnahmen des nationalen Emissionshandels (rund 16 Mrd. Euro 2025) fließen bisher vollständig in den Klima- und Transformationsfonds; bei Rückzahlung fehlten sie dort.","quelle_url":"https://www.umweltbundesamt.de/presse/pressemitteilungen/emissionshandel-21-milliarden-euro-fliessen-in-den","belegstufe":"A"},{"bereich":"verteilung","richtung":"vorteil","text":"Eine pauschale Auszahlung pro Kopf enthält laut DIW wegen des nach Einkommen unterschiedlichen CO₂-Fußabdrucks bereits eine öko-soziale Komponente: Geringere Einkommen profitieren relativ stärker.","quelle_url":"https://www.diw.de/de/diw_01.c.935747.de/publikationen/wochenberichte/2025_06_1/mehr_klarheit_schaffen__klimageld_als_sozialer_ausgleich_bei_hoeheren_co___-preisen.html","belegstufe":"B"}]'::jsonb),
  (7025, 15, 14, null, 'Energiesteuer auf Kraftstoffe bis auf null abschmelzen, CO₂-Preis soll sie ersetzen, Kfz-Steuer abschaffen', '{1502}', null, 1, 1, null, 'Ersetzt eine Steuer durch den CO₂-Preis; ob Sprit dadurch billiger wird, hängt von dessen Höhe ab. Die EU-Mindestsätze kann Deutschland nicht allein ändern.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=17', null, 'offen', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Die Einnahmen betrugen 2024 bei der Energiesteuer 36,6 Mrd. Euro und bei der Kfz-Steuer 9,7 Mrd. Euro (UBA, vorläufig); sie sänken mit dem Abschmelzen bzw. der Abschaffung entsprechend.","quelle_url":"https://www.umweltbundesamt.de/daten/umweltindikatoren/indikator-umweltbezogene-steuern","belegstufe":"A"},{"bereich":"umwelt","richtung":"nachteil","text":"Zum Vergleich: Die befristete Energiesteuersenkung auf Kraftstoffe 2026 begünstigt laut Gesetzentwurf den Einsatz fossiler Energien vorübergehend; das ist nicht die Wirkung dieser Maßnahme.","quelle_url":"https://www.bundestag.de/presse/hib/kurzmeldungen-1165456","belegstufe":"A"}]'::jsonb),
  (7026, 15, 15, null, 'Energiesteuer senken', '{1502}', null, 2, 2, null, 'Senkt den Spritpreis direkt; die Tankrabatte 2022 und 2026 wurden laut Monopolkommission großteils weitergegeben. Eine dauerhafte Senkung kostet je 10 Cent mehrere Milliarden Euro im Jahr, eine Gegenfinanzierung nennt das Programm nicht.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=14', 'https://www.monopolkommission.de/fileadmin/monopolkommission/Indexierte_Dateien/PDFs/Policy_Briefs/Monopolkommission-Policy-Brief-16-2026-Tankrabatt.pdf', 'belegt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Die befristete Senkung um 14,04 Cent je Liter von Mai bis Juni 2026 kostete laut Gesetzentwurf 1,6 Mrd. Euro; das sind nicht die Kosten einer dauerhaften Senkung.","quelle_url":"https://www.bundestag.de/presse/hib/kurzmeldungen-1165456","belegstufe":"A"},{"bereich":"umwelt","richtung":"nachteil","text":"Laut Gesetzentwurf begünstigt eine Senkung der Energiesteuer den Einsatz fossiler Energien vorübergehend und kann den Kraftstoffverbrauch zeitweise steigern.","quelle_url":"https://www.bundestag.de/presse/hib/kurzmeldungen-1165456","belegstufe":"A"},{"bereich":"verteilung","richtung":"nachteil","text":"Zum Vergleich (Tankrabatt 2022): Laut DIW entlastet er eher wohlhabende Haushalte, die viel mit großen Autos fahren, und wirkt wie eine Umverteilung von unten nach oben.","quelle_url":"https://www.diw.de/de/diw_01.c.861731.de/nachrichten/entlastung_fuer_autofahrer__der_tankrabatt_ist_das_naheliegendste__aber_auch_schlechteste_instrument.html","belegstufe":"B"}]'::jsonb),
  (7027, 15, 15, null, 'CO₂-Abgaben ersatzlos abschaffen', '{1502}', 7011, 2, 1, null, 'Senkt den Spritpreis 2026 um rund 15 bis 18 Cent je Liter; ab 2028 gilt aber der europäische Emissionshandel für Verkehr, den Deutschland nicht allein abschaffen kann. Die Einnahmen fehlen für Entlastungen an anderer Stelle.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=58', null, 'belegt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Der nationale Emissionshandel brachte 2025 rund 16 Mrd. Euro ein, die vollständig in den Klima- und Transformationsfonds fließen; bei Abschaffung des CO₂-Preises entfielen sie dort.","quelle_url":"https://www.umweltbundesamt.de/presse/pressemitteilungen/emissionshandel-21-milliarden-euro-fliessen-in-den","belegstufe":"A"},{"bereich":"umwelt","richtung":"nachteil","text":"Eine UBA-Modellierung beziffert die zusätzliche Minderung durch einen CO₂-Preis im Verkehr auf 7 Mio. t CO₂-Äq. im Jahr 2030 (kumuliert 116 Mio. t bis 2045); ohne ihn entfiele sie.","quelle_url":"https://www.umweltbundesamt.de/themen/verkehr/klimaschutz-im-verkehr","belegstufe":"B"}]'::jsonb),
  (7028, 15, 16, null, 'Soziales Klimageld von 320 Euro im Jahr pro Person', '{1502}', 7012, 1, 2, null, 'Gleicht die Mehrkosten durch den CO₂-Preis für viele Haushalte aus, senkt den Spritpreis aber nicht; wer viel fahren muss, wird nur teilweise entlastet. Ein Auszahlungsweg an alle Haushalte muss erst aufgebaut werden.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=7', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Die Einnahmen des nationalen Emissionshandels (rund 16 Mrd. Euro 2025) fließen bisher vollständig in den Klima- und Transformationsfonds; bei Rückzahlung fehlten sie dort.","quelle_url":"https://www.umweltbundesamt.de/presse/pressemitteilungen/emissionshandel-21-milliarden-euro-fliessen-in-den","belegstufe":"A"},{"bereich":"verteilung","richtung":"vorteil","text":"Eine pauschale Auszahlung pro Kopf enthält laut DIW wegen des nach Einkommen unterschiedlichen CO₂-Fußabdrucks bereits eine öko-soziale Komponente: Geringere Einkommen profitieren relativ stärker.","quelle_url":"https://www.diw.de/de/diw_01.c.935747.de/publikationen/wochenberichte/2025_06_1/mehr_klarheit_schaffen__klimageld_als_sozialer_ausgleich_bei_hoeheren_co___-preisen.html","belegstufe":"B"}]'::jsonb),
  (7029, 15, 16, null, 'Sozial gestaffelte Förderung kleiner E-Fahrzeuge für Pendelnde auf dem Land', '{1504}', 7014, 2, 3, null, 'Setzt direkt am Preis an, den Haushalte als größtes Hindernis nennen; soziales Leasing hat in Frankreich viele Haushalte mit kleinem Einkommen erreicht. Frühere Prämien in Deutschland wurden zum Teil mitgenommen und kamen vor allem besser Verdienenden zugute.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=32', 'https://www.kfw.de/PDF/Download-Center/Konzernthemen/Research/PDF-Dokumente-KfW-Energiewendebarometer/KfW-Energiewendebarometer-2026.pdf', 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Der frühere Umweltbonus (2016–2023) umfasste bewilligte Fördermittel von 10,2 Mrd. Euro für rund 2,17 Mio. Fahrzeuge; das sind nicht die Kosten dieser Maßnahme.","quelle_url":"https://technopolis-group.com/?p=61750","belegstufe":"B"},{"bereich":"umwelt","richtung":"vorteil","text":"Zum Vergleich: Der frühere Umweltbonus (2016–2023) brachte laut Evaluation brutto 7,3 Mt CO₂-Äq. Treibhausgaseinsparung; das ist nicht die Wirkung dieser Maßnahme.","quelle_url":"https://technopolis-group.com/?p=61750","belegstufe":"B"},{"bereich":"verteilung","richtung":"nachteil","text":"Zum Vergleich: Die frühere Umweltbonus-Förderung nutzten laut Evaluation überproportional Haushalte mit höherem Nettoeinkommen; die Evaluation spricht von einem unerwünschten Verteilungseffekt.","quelle_url":"https://technopolis-group.com/?p=61750","belegstufe":"B"}]'::jsonb),
  (7030, 15, 16, null, 'Investitionen in öffentliche Ladeinfrastruktur mit günstigen Tarifen', '{1505}', 7015, 1, 3, null, 'Hilft, wer nicht zu Hause laden kann, vor allem in Mehrparteienhäusern; öffentliches Laden bleibt aber meist teurer und aufwendiger als eine eigene Wallbox.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=32', null, 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Der Haushaltsentwurf 2026 sieht für die Errichtung von Tank- und Ladeinfrastruktur 1,7 Mrd. Euro vor; das sind nicht die Kosten dieser Maßnahme.","quelle_url":"https://www.bundestag.de/presse/hib/kurzmeldungen-1111618","belegstufe":"A"}]'::jsonb),
  (7031, 15, 16, null, 'Pendlerpauschale durch ein Mobilitätsgeld ersetzen', '{1502}', null, 1, 3, null, 'Ein fester Betrag je Kilometer entlastet Pendelnde mit kleinem Einkommen stärker als die Pauschale, besser Verdienende weniger; der Spritpreis selbst ändert sich nicht.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=36', null, 'offen', '2026-09-30', false, true, null, '[]'::jsonb),
  (7032, 15, 17, null, 'CO₂-Preis abschaffen', '{1502}', 7011, 2, 1, null, 'Senkt den Spritpreis 2026 um rund 15 bis 18 Cent je Liter; ab 2028 gilt aber der europäische Emissionshandel für Verkehr, den Deutschland nicht allein abschaffen kann. Die Einnahmen fehlen für Entlastungen an anderer Stelle.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=10', null, 'belegt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Der nationale Emissionshandel brachte 2025 rund 16 Mrd. Euro ein, die vollständig in den Klima- und Transformationsfonds fließen; bei Abschaffung des CO₂-Preises entfielen sie dort.","quelle_url":"https://www.umweltbundesamt.de/presse/pressemitteilungen/emissionshandel-21-milliarden-euro-fliessen-in-den","belegstufe":"A"},{"bereich":"umwelt","richtung":"nachteil","text":"Eine UBA-Modellierung beziffert die zusätzliche Minderung durch einen CO₂-Preis im Verkehr auf 7 Mio. t CO₂-Äq. im Jahr 2030 (kumuliert 116 Mio. t bis 2045); ohne ihn entfiele sie.","quelle_url":"https://www.umweltbundesamt.de/themen/verkehr/klimaschutz-im-verkehr","belegstufe":"B"}]'::jsonb),
  (7033, 15, 17, null, 'Volksleasing für umweltfreundliche Fahrzeuge aus europäischer Produktion, Kaufprämien im niedrigen Preissegment', '{1504}', 7014, 2, 3, null, 'Setzt direkt am Preis an, den Haushalte als größtes Hindernis nennen; soziales Leasing hat in Frankreich viele Haushalte mit kleinem Einkommen erreicht. Frühere Prämien in Deutschland wurden zum Teil mitgenommen und kamen vor allem besser Verdienenden zugute.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=29', 'https://www.kfw.de/PDF/Download-Center/Konzernthemen/Research/PDF-Dokumente-KfW-Energiewendebarometer/KfW-Energiewendebarometer-2026.pdf', 'gemischt', '2026-09-30', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Der frühere Umweltbonus (2016–2023) umfasste bewilligte Fördermittel von 10,2 Mrd. Euro für rund 2,17 Mio. Fahrzeuge; das sind nicht die Kosten dieser Maßnahme.","quelle_url":"https://technopolis-group.com/?p=61750","belegstufe":"B"},{"bereich":"umwelt","richtung":"vorteil","text":"Zum Vergleich: Der frühere Umweltbonus (2016–2023) brachte laut Evaluation brutto 7,3 Mt CO₂-Äq. Treibhausgaseinsparung; das ist nicht die Wirkung dieser Maßnahme.","quelle_url":"https://technopolis-group.com/?p=61750","belegstufe":"B"},{"bereich":"verteilung","richtung":"nachteil","text":"Zum Vergleich: Die frühere Umweltbonus-Förderung nutzten laut Evaluation überproportional Haushalte mit höherem Nettoeinkommen; die Evaluation spricht von einem unerwünschten Verteilungseffekt.","quelle_url":"https://technopolis-group.com/?p=61750","belegstufe":"B"}]'::jsonb),
  (7261, 15, 12, null, 'Befristeter Steuerabzugsbetrag für in Deutschland produzierte E-Autos, auch Gebrauchte und Leasing', '{1501}', 7258, 1, 3, null, 'Jedes ersetzte Verbrennerfahrzeug braucht kein Benzin oder Diesel mehr. Bei 4,1 % Elektroanteil im Pkw-Bestand (1. 1. 2026) und langer Erneuerungszeit wirkt das erst über Jahre und schützt nicht vor einem Preisschock im laufenden Jahr.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=7', 'https://www.kba.de/DE/Presse/Pressemitteilungen/Fahrzeugbestand/2026/pm09_fz_bestand_pm_komplett.html', 'gemischt', '2026-10-01', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Das 2026 gestartete Bundesprogramm für E-Auto-Prämien umfasst 3 Mrd. Euro bis 2029 für geschätzt 800.000 Fahrzeuge; es sind nicht die Kosten dieser Maßnahme.","quelle_url":"https://www.bundesumweltministerium.de/PM11760","belegstufe":"A"},{"bereich":"umwelt","richtung":"vorteil","text":"Laut Umweltbundesamt sind 2020 zugelassene Elektroautos über den gesamten Lebenszyklus rund 40 Prozent klimafreundlicher als Benziner; für 2030 werden rund 55 Prozent erwartet.","quelle_url":"https://www.umweltbundesamt.de/en/press/pressinformation/climate-benefit-for-electric-cars-confirmed","belegstufe":"A"}]'::jsonb),
  (7262, 15, 13, null, 'Staatliche Unterstützung beim Kauf verbrauchsarmer E-Autos, Social Leasing, Ladekarte', '{1501}', 7258, 1, 3, null, 'Jedes ersetzte Verbrennerfahrzeug braucht kein Benzin oder Diesel mehr. Bei 4,1 % Elektroanteil im Pkw-Bestand (1. 1. 2026) und langer Erneuerungszeit wirkt das erst über Jahre und schützt nicht vor einem Preisschock im laufenden Jahr.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=40', 'https://www.kba.de/DE/Presse/Pressemitteilungen/Fahrzeugbestand/2026/pm09_fz_bestand_pm_komplett.html', 'gemischt', '2026-10-01', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Das 2026 gestartete Bundesprogramm für E-Auto-Prämien umfasst 3 Mrd. Euro bis 2029 für geschätzt 800.000 Fahrzeuge; es sind nicht die Kosten dieser Maßnahme.","quelle_url":"https://www.bundesumweltministerium.de/PM11760","belegstufe":"A"},{"bereich":"umwelt","richtung":"vorteil","text":"Laut Umweltbundesamt sind 2020 zugelassene Elektroautos über den gesamten Lebenszyklus rund 40 Prozent klimafreundlicher als Benziner; für 2030 werden rund 55 Prozent erwartet.","quelle_url":"https://www.umweltbundesamt.de/en/press/pressinformation/climate-benefit-for-electric-cars-confirmed","belegstufe":"A"}]'::jsonb),
  (7263, 15, 16, null, 'Sozial gestaffelte Förderung kleiner E-Fahrzeuge für Pendelnde auf dem Land', '{1501}', 7258, 1, 3, null, 'Jedes ersetzte Verbrennerfahrzeug braucht kein Benzin oder Diesel mehr. Bei 4,1 % Elektroanteil im Pkw-Bestand (1. 1. 2026) und langer Erneuerungszeit wirkt das erst über Jahre und schützt nicht vor einem Preisschock im laufenden Jahr.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=32', 'https://www.kba.de/DE/Presse/Pressemitteilungen/Fahrzeugbestand/2026/pm09_fz_bestand_pm_komplett.html', 'gemischt', '2026-10-01', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Das 2026 gestartete Bundesprogramm für E-Auto-Prämien umfasst 3 Mrd. Euro bis 2029 für geschätzt 800.000 Fahrzeuge; es sind nicht die Kosten dieser Maßnahme.","quelle_url":"https://www.bundesumweltministerium.de/PM11760","belegstufe":"A"},{"bereich":"umwelt","richtung":"vorteil","text":"Laut Umweltbundesamt sind 2020 zugelassene Elektroautos über den gesamten Lebenszyklus rund 40 Prozent klimafreundlicher als Benziner; für 2030 werden rund 55 Prozent erwartet.","quelle_url":"https://www.umweltbundesamt.de/en/press/pressinformation/climate-benefit-for-electric-cars-confirmed","belegstufe":"A"}]'::jsonb),
  (7264, 15, 17, null, 'Volksleasing für umweltfreundliche Fahrzeuge aus europäischer Produktion, Kaufprämien im niedrigen Preissegment', '{1501}', 7258, 1, 3, null, 'Jedes ersetzte Verbrennerfahrzeug braucht kein Benzin oder Diesel mehr. Bei 4,1 % Elektroanteil im Pkw-Bestand (1. 1. 2026) und langer Erneuerungszeit wirkt das erst über Jahre und schützt nicht vor einem Preisschock im laufenden Jahr.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=29', 'https://www.kba.de/DE/Presse/Pressemitteilungen/Fahrzeugbestand/2026/pm09_fz_bestand_pm_komplett.html', 'gemischt', '2026-10-01', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Das 2026 gestartete Bundesprogramm für E-Auto-Prämien umfasst 3 Mrd. Euro bis 2029 für geschätzt 800.000 Fahrzeuge; es sind nicht die Kosten dieser Maßnahme.","quelle_url":"https://www.bundesumweltministerium.de/PM11760","belegstufe":"A"},{"bereich":"umwelt","richtung":"vorteil","text":"Laut Umweltbundesamt sind 2020 zugelassene Elektroautos über den gesamten Lebenszyklus rund 40 Prozent klimafreundlicher als Benziner; für 2030 werden rund 55 Prozent erwartet.","quelle_url":"https://www.umweltbundesamt.de/en/press/pressinformation/climate-benefit-for-electric-cars-confirmed","belegstufe":"A"}]'::jsonb),
  (7265, 15, 11, null, 'Technologieoffenheit: E-Fuels, Wasserstoff und nachhaltige Biokraftstoffe neben der Elektromobilität nutzen', '{1501}', 7259, 1, 1, null, 'Strombasierte Kraftstoffe entkoppeln den Preis vom Rohöl, sind aber nicht kommerziell verfügbar und würden zunächst etwa 2 Euro je Liter kosten (Benzin im Großhandel 0,50). Bis 2035 deckt es höchstens die Hälfte des Bedarfs von Luft-, Schifffahrt und Chemie. Das Verbrennerverbot ist EU-Recht.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=75', 'https://www.pik-potsdam.de/members/Ueckerdt/E-Fuels_Stand-und-Projektionen_PIK-Potsdam.pdf', 'offen', '2026-10-01', false, true, null, '[{"bereich":"umwelt","richtung":"nachteil","text":"Laut Umweltbundesamt brauchen strombasierte Kraftstoffe im Pkw für dieselbe Fahrleistung die drei- bis sechsfache Strommenge eines Elektroautos und gelten als hochgradig ineffizient.","quelle_url":"https://www.umweltbundesamt.de/themen/verkehr/kraftstoffe-antriebe","belegstufe":"A"}]'::jsonb),
  (7266, 15, 14, null, 'Statt eines Verbrennerverbots alternative Kraftstoffe wie E-Fuels ermöglichen', '{1501}', 7259, 1, 1, null, 'Strombasierte Kraftstoffe entkoppeln den Preis vom Rohöl, sind aber nicht kommerziell verfügbar und würden zunächst etwa 2 Euro je Liter kosten (Benzin im Großhandel 0,50). Bis 2035 deckt es höchstens die Hälfte des Bedarfs von Luft-, Schifffahrt und Chemie. Das Verbrennerverbot ist EU-Recht.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=42', 'https://www.pik-potsdam.de/members/Ueckerdt/E-Fuels_Stand-und-Projektionen_PIK-Potsdam.pdf', 'offen', '2026-10-01', false, true, null, '[{"bereich":"umwelt","richtung":"nachteil","text":"Laut Umweltbundesamt brauchen strombasierte Kraftstoffe im Pkw für dieselbe Fahrleistung die drei- bis sechsfache Strommenge eines Elektroautos und gelten als hochgradig ineffizient.","quelle_url":"https://www.umweltbundesamt.de/themen/verkehr/kraftstoffe-antriebe","belegstufe":"A"}]'::jsonb),
  (7267, 15, 15, null, 'Synthetische Kraftstoffe berücksichtigen und bei den Abgaben wie Elektrofahrzeuge behandeln', '{1501}', 7259, 1, 1, null, 'Strombasierte Kraftstoffe entkoppeln den Preis vom Rohöl, sind aber nicht kommerziell verfügbar und würden zunächst etwa 2 Euro je Liter kosten (Benzin im Großhandel 0,50). Bis 2035 deckt es höchstens die Hälfte des Bedarfs von Luft-, Schifffahrt und Chemie. Das Verbrennerverbot ist EU-Recht.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=44', 'https://www.pik-potsdam.de/members/Ueckerdt/E-Fuels_Stand-und-Projektionen_PIK-Potsdam.pdf', 'offen', '2026-10-01', false, true, null, '[{"bereich":"umwelt","richtung":"nachteil","text":"Laut Umweltbundesamt brauchen strombasierte Kraftstoffe im Pkw für dieselbe Fahrleistung die drei- bis sechsfache Strommenge eines Elektroautos und gelten als hochgradig ineffizient.","quelle_url":"https://www.umweltbundesamt.de/themen/verkehr/kraftstoffe-antriebe","belegstufe":"A"}]'::jsonb),
  (7268, 15, 17, null, 'Verbrauchsarme Verbrenner und alternative Kraftstoffe fördern', '{1501}', 7259, 1, 1, null, 'Strombasierte Kraftstoffe entkoppeln den Preis vom Rohöl, sind aber nicht kommerziell verfügbar und würden zunächst etwa 2 Euro je Liter kosten (Benzin im Großhandel 0,50). Bis 2035 deckt es höchstens die Hälfte des Bedarfs von Luft-, Schifffahrt und Chemie. Das Verbrennerverbot ist EU-Recht.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=10', 'https://www.pik-potsdam.de/members/Ueckerdt/E-Fuels_Stand-und-Projektionen_PIK-Potsdam.pdf', 'offen', '2026-10-01', false, true, null, '[{"bereich":"umwelt","richtung":"nachteil","text":"Laut Umweltbundesamt brauchen strombasierte Kraftstoffe im Pkw für dieselbe Fahrleistung die drei- bis sechsfache Strommenge eines Elektroautos und gelten als hochgradig ineffizient.","quelle_url":"https://www.umweltbundesamt.de/themen/verkehr/kraftstoffe-antriebe","belegstufe":"A"}]'::jsonb),
  (7269, 15, 11, null, 'In angespannter Lage Energie- und Umsatzsteuer für Güter des täglichen Bedarfs schnell senken dürfen', '{1501}', 7260, 1, 1, null, 'Senkt den Preis sofort, aber nur befristet; der Tankrabatt 2026 kam laut Monopolkommission zu einem großen Teil, aber nicht vollständig an. Die schnelle Senkung der Umsatzsteuer braucht EU-Zustimmung. Das Programm nennt Güter des täglichen Bedarfs, nicht nur Kraftstoff.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=14', 'https://www.monopolkommission.de/fileadmin/monopolkommission/Indexierte_Dateien/PDFs/Policy_Briefs/Monopolkommission-Policy-Brief-16-2026-Tankrabatt.pdf#page=1', 'gemischt', '2026-10-01', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Zum Vergleich: Die befristete Senkung um 14,04 Cent je Liter von Mai bis Juni 2026 kostete laut Gesetzentwurf 1,6 Mrd. Euro; das sind nicht die Kosten dieser Maßnahme.","quelle_url":"https://www.bundestag.de/presse/hib/kurzmeldungen-1165456","belegstufe":"A"},{"bereich":"umwelt","richtung":"nachteil","text":"Laut Gesetzentwurf begünstigt eine Senkung der Energiesteuer den Einsatz fossiler Energien vorübergehend und kann den Kraftstoffverbrauch zeitweise steigern.","quelle_url":"https://www.bundestag.de/presse/hib/kurzmeldungen-1165456","belegstufe":"A"},{"bereich":"verteilung","richtung":"nachteil","text":"Zum Vergleich (Tankrabatt 2022): Laut DIW entlastet er eher wohlhabende Haushalte, die viel mit großen Autos fahren, und wirkt wie eine Umverteilung von unten nach oben.","quelle_url":"https://www.diw.de/de/diw_01.c.861731.de/nachrichten/entlastung_fuer_autofahrer__der_tankrabatt_ist_das_naheliegendste__aber_auch_schlechteste_instrument.html","belegstufe":"B"}]'::jsonb),
  (7270, 15, 11, null, 'Europäischen Energiebinnenmarkt stärken, internationale Energiepartnerschaften ausbauen', '{1501}', null, 1, 3, null, 'Mehr Lieferländer machen Deutschland weniger anfällig für Preissprünge bei einzelnen Lieferanten; die Maßnahme nennt weder Öl noch konkrete Schritte.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=22', null, 'offen', '2026-10-01', false, true, null, '[]'::jsonb),
  (7271, 15, 17, null, 'Langfristige Lieferverträge für Energieimporte nach dem niedrigsten Preis', '{1501}', null, 1, 2, null, 'Langfristige Verträge können Preisschwankungen dämpfen, binden aber auch an Preise, wenn der Markt fällt; die Maßnahme nennt kein Öl, sondern Energieimporte allgemein.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=10', null, 'offen', '2026-10-01', false, true, null, '[]'::jsonb),
  (8001, 15, 16, null, 'Ablehnung des europäischen Emissionshandels für Wärme und Verkehr (ETS-2); stattdessen verbindliche Klimaziele und Emissionsgrenzen, damit kein CO₂-Preis auf Kraftstoffe entsteht.', '{1502}', 7011, 2, 1, null, 'Senkt den Spritpreis 2026 um rund 15 bis 18 Cent je Liter; ab 2028 gilt aber der europäische Emissionshandel für Verkehr, den Deutschland nicht allein abschaffen kann. Die Einnahmen fehlen für Entlastungen an anderer Stelle.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=33', null, 'belegt', '2026-10-05', false, true, null, '[{"bereich":"haushalt","richtung":"nachteil","text":"Der nationale Emissionshandel brachte 2025 rund 16 Mrd. Euro ein, die vollständig in den Klima- und Transformationsfonds fließen; bei Abschaffung des CO₂-Preises entfielen sie dort.","quelle_url":"https://www.umweltbundesamt.de/presse/pressemitteilungen/emissionshandel-21-milliarden-euro-fliessen-in-den","belegstufe":"A"},{"bereich":"umwelt","richtung":"nachteil","text":"Eine UBA-Modellierung beziffert die zusätzliche Minderung durch einen CO₂-Preis im Verkehr auf 7 Mio. t CO₂-Äq. im Jahr 2030 (kumuliert 116 Mio. t bis 2045); ohne ihn entfiele sie.","quelle_url":"https://www.umweltbundesamt.de/themen/verkehr/klimaschutz-im-verkehr","belegstufe":"B"}]'::jsonb);

